async function getJson<T>(path:string):Promise<T>{const response=await fetch(path,{credentials:"same-origin"});const body=await response.json() as T&{error?:string};if(!response.ok)throw new Error(body.error??"request_failed");return body;}
const navigate=(path:string)=>{navigateToHash(path);window.scrollTo({top:0,behavior:"smooth"});};

function useLearningRoute(){
  const read=()=>window.location.hash.startsWith("#/learn/en")?window.location.hash.slice(1):window.location.pathname.startsWith("/learn/en")?window.location.pathname:"/learn/en";
  const [route,setRoute]=useState(read);
  useEffect(()=>{const update=()=>setRoute(read());window.addEventListener("hashchange",update);window.addEventListener("popstate",update);return()=>{window.removeEventListener("hashchange",update);window.removeEventListener("popstate",update);};},[]);
  return route;
}

export function EnglishLearningApp({locale,onHome,header,canonicalPath}:{locale:UiLocale;onHome:()=>void;header:React.ReactNode;canonicalPath?:string}){
  const manifestState=useLessonManifest();
  const route=useLearningRoute(),lesson=route.match(/^\/learn\/en\/lesson\/([\w-]+)$/u),section=route.match(/^\/learn\/en\/([\w-]+)\/([\w-]+)$/u),category=route.match(/^\/learn\/en\/([\w-]+)$/u);
  const canonical=canonicalPath?.match(/^\/lessons\/([^/]+)\/([^/]+)\/([^/]+)$/u);
  const content=canonical?<DictationLesson manifest={manifestState.manifest} lessonPath={{level:canonical[1],category:canonical[2],slug:canonical[3]}} locale={locale} onHome={onHome}/>:lesson?<DictationLesson manifest={manifestState.manifest} lessonSlug={lesson[1]} locale={locale} onHome={onHome}/>:manifestState.failed?<Shell locale={locale} onHome={onHome} title="English"><LoadError locale={locale} retry={manifestState.retry}/></Shell>:section?<LessonList manifest={manifestState.manifest} categorySlug={section[1]} sectionId={section[2]} locale={locale} onHome={onHome}/>:category?<SectionList manifest={manifestState.manifest} categorySlug={category[1]} locale={locale} onHome={onHome}/>:<CategoryList manifest={manifestState.manifest} locale={locale} onHome={onHome}/>;
  return <><div className="learning-page-header">{header}</div>{content}</>;
}
