interface ManagedLesson {id:string;title:string;slug:string;path:string;level:string|null;description:string|null;sort_order:number;section_id:string;section_title:string;category_name:string;language_code:string;is_published:boolean;updated_at:string;sentences?:ReviewSentence[];}

export function LessonManagementPage({onHome,locale}:{onHome:()=>void;locale:UiLocale}){
  const auth=useAuth();
  const title=adminSystemT(locale,"lessonsTitle");
  const t=(key:Parameters<typeof lessonManagementT>[1],values?:Record<string,string|number>)=>lessonManagementT(locale,key,values);
  const [items,setItems]=useState<ManagedLesson[]>([]),[sections,setSections]=useState<Array<{section_id:string;category_name:string;section_title:string}>>([]),[query,setQuery]=useState(""),[status,setStatus]=useState("all"),[language,setLanguage]=useState("all"),[selected,setSelected]=useState<ManagedLesson>(),[sentencesJson,setSentencesJson]=useState("[]"),[error,setError]=useState(""),[busy,setBusy]=useState(false);
  const load=()=>{if(!auth.user?.isAdmin)return;void Promise.all([getJson<{lessons:ManagedLesson[]}>(`/api/listening/admin/lessons?q=${encodeURIComponent(query)}&status=${encodeURIComponent(status)}&language=${encodeURIComponent(language)}`),getJson<{sections:typeof sections}>("/api/listening/admin/bootstrap")]).then(([lessonData,bootstrap])=>{setItems(lessonData.lessons);setSections(bootstrap.sections);setError("");}).catch(()=>setError(t("loadError")));};
  useEffect(load,[auth.user?.isAdmin,query,status,language]);
  if(auth.loading)return <AdminLayout locale={locale} title={title} onSiteHome={onHome}><div className="admin-state">{adminSystemT(locale,"loading")}</div></AdminLayout>;
  if(!auth.user?.isAdmin)return <AdminLayout locale={locale} title={title} onSiteHome={onHome}><div className="admin-state">{adminSystemT(locale,"adminRequired")}</div></AdminLayout>;
  const open=async(id:string)=>{setBusy(true);setError("");try{const result=await getJson<{lesson:ManagedLesson}>(`/api/listening/admin/lessons/${encodeURIComponent(id)}`);setSelected(result.lesson);setSentencesJson(JSON.stringify(result.lesson.sentences??[],null,2));}catch{setError(t("openError"));}finally{setBusy(false);}};
  const save=async()=>{if(!selected)return;setBusy(true);setError("");try{const sentences=JSON.parse(sentencesJson) as unknown;await auth.adminUpdateLesson(selected.id,{title:selected.title,slug:selected.slug,level:selected.level,description:selected.description,sortOrder:selected.sort_order,sectionId:selected.section_id,sentences});setSelected(undefined);load();}catch{setError(t("updateError"));}finally{setBusy(false);}};
  const remove=async(item:ManagedLesson)=>{if(!window.confirm(t("deleteConfirm",{title:item.title})))return;setBusy(true);setError("");try{await auth.adminDeleteLesson(item.id);if(selected?.id===item.id)setSelected(undefined);load();}catch{setError(t("deleteError"));}finally{setBusy(false);}};
  return <AdminLayout locale={locale} title={title} onSiteHome={onHome}>
    <button className="admin-inline-link" type="button" onClick={()=>navigate("/admin/listening")}>{adminSystemT(locale,"importTitle")}</button>
    <div className="admin-filters"><input aria-label={t("searchLessons")} value={query} onChange={event=>setQuery(event.target.value)} placeholder={t("searchPlaceholder")}/><select aria-label={t("status")} value={status} onChange={event=>setStatus(event.target.value)}><option value="all">{t("allStatuses")}</option><option value="published">{t("published")}</option><option value="draft">{t("draft")}</option></select><select aria-label={t("language")} value={language} onChange={event=>setLanguage(event.target.value)}><option value="all">{t("allLanguages")}</option><option value="en">{t("english")}</option><option value="zh">{t("chinese")}</option><option value="ja">{t("japanese")}</option></select></div>
    {error&&<p className="form-error" role="alert">{error}</p>}
    {selected?<form className="admin-import" onSubmit={event=>{event.preventDefault();void save();}}><label>{t("lessonId")}<input readOnly value={selected.id}/></label><label>{t("title")}<input required value={selected.title} onChange={event=>setSelected({...selected,title:event.target.value})}/></label><label>{t("slug")}<input required value={selected.slug} onChange={event=>setSelected({...selected,slug:event.target.value})}/></label><label>{t("level")}<input value={selected.level??""} onChange={event=>setSelected({...selected,level:event.target.value})}/></label><label>{t("description")}<textarea value={selected.description??""} onChange={event=>setSelected({...selected,description:event.target.value})}/></label><label>{t("placement")}<select value={selected.section_id} onChange={event=>setSelected({...selected,section_id:event.target.value})}>{sections.map(item=><option key={item.section_id} value={item.section_id}>{item.category_name} · {item.section_title}</option>)}</select></label><label>{t("order")}<input type="number" min={0} value={selected.sort_order} onChange={event=>setSelected({...selected,sort_order:Number(event.target.value)})}/></label><label>{t("scriptJson")}<textarea required value={sentencesJson} onChange={event=>setSentencesJson(event.target.value)}/><small>{t("scriptHint")}</small></label><div><button type="button" onClick={()=>setSelected(undefined)}>{t("cancel")}</button><button className="primary-button" disabled={busy}>{t("saveChanges")}</button></div></form>:<div className="admin-lesson-list">{items.map(item=><article key={item.id}><button type="button" disabled={busy} onClick={()=>void open(item.id)}>{item.title}</button><small>{item.id} · {item.path} · {item.level??"—"} · {t(item.is_published?"published":"draft")} · {new Date(item.updated_at).toLocaleString(localeTags[locale])}</small>{item.is_published&&<a href={item.path} onClick={event=>followPathLink(event,item.path)}>{t("open")}</a>}<button type="button" disabled={busy} onClick={()=>void remove(item)}>{t("delete")}</button></article>)}</div>}
  </AdminLayout>;
}

function mediaDuration(file:File){return new Promise<number>((resolve,reject)=>{const audio=new Audio(),url=URL.createObjectURL(file);audio.preload="metadata";audio.onloadedmetadata=()=>{const duration=Math.round(audio.duration*1000);URL.revokeObjectURL(url);Number.isFinite(duration)&&duration>0?resolve(duration):reject(new Error("Invalid audio duration"));};audio.onerror=()=>{URL.revokeObjectURL(url);reject(new Error("Audio metadata could not be read"));};audio.src=url;});}
function playFileSegment(file:File,startMs:number,endMs:number){const audio=new Audio(URL.createObjectURL(file));audio.currentTime=startMs/1000;void audio.play();const stop=()=>{if(audio.currentTime>=endMs/1000){audio.pause();URL.revokeObjectURL(audio.src);}else requestAnimationFrame(stop);};requestAnimationFrame(stop);}

